/// Evaluates decode condition `id` against instruction word `w`.
#[allow(clippy::all, unused_parens)]
pub fn condition(id: u16, w: u32, state: State) -> bool {
    let _ = state;
    let w = w as u64;
    match id {
        1 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))),
        2 => (!(state.in_it_block)),
        3 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 11) & 0x3) as i64) != (0x3 as i64))) && (((((w >> 11) & 0x3) as i64) != (0x3 as i64))),
        4 => ((((((w >> 11) & 0x3) as i64) != (0x3 as i64)) && ((((w >> 11) & 0x3) as i64) == (0x2 as i64)))),
        5 => ((((((w >> 11) & 0x3) as i64) != (0x3 as i64)) && ((((w >> 11) & 0x3) as i64) == (0x1 as i64)))),
        6 => (state.in_it_block),
        7 => ((((((w >> 11) & 0x3) as i64) != (0x3 as i64)) && (((((w >> 11) & 0x3) as i64) == (0x0 as i64)) && ((((w >> 6) & 0x1f) as i64) != (0x0 as i64))))),
        8 => (((((w >> 11) & 0x3) as i64) != (0x3 as i64))),
        9 => ((state.in_it_block && ((((w >> 0) & 0xff) as i64) >= (8 as i64)))),
        10 => ((!(state.in_it_block) && ((((w >> 0) & 0xff) as i64) < (8 as i64)))),
        11 => ((!(state.in_it_block) && ((((w >> 0) & 0xff) as i64) >= (8 as i64)))),
        12 => ((state.in_it_block && !((((((w >> 8) & 0x7) as i64) < (8 as i64)) && ((((w >> 0) & 0xff) as i64) < (8 as i64)))))),
        13 => (((!(state.in_it_block) && ((((w >> 8) & 0x7) as i64) < (8 as i64))) && ((((w >> 0) & 0xff) as i64) < (8 as i64)))),
        14 => ((!(state.in_it_block) && !((((((w >> 8) & 0x7) as i64) < (8 as i64)) && ((((w >> 0) & 0xff) as i64) < (8 as i64)))))),
        15 => (((((w >> 6) & 0xf) as i64) == (0x4 as i64))),
        16 => (((((w >> 6) & 0xf) as i64) == (0x2 as i64))),
        17 => (((((w >> 6) & 0xf) as i64) == (0x3 as i64))),
        18 => (((((w >> 6) & 0xf) as i64) == (0x7 as i64))),
        19 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 8) & 0x3) as i64) != (0x3 as i64))) && ((!((((((w >> 7) & 0x1) as i64) == (0x1 as i64)) && ((((w >> 0) & 0x7) as i64) == (0x5 as i64)))) && ((((w >> 3) & 0xf) as i64) != (0xd as i64)))),
        20 => ((!((((((w >> 7) & 0x1) as i64) == (0x1 as i64)) && ((((w >> 0) & 0x7) as i64) == (0x5 as i64)))) && ((((w >> 3) & 0xf) as i64) != (0xd as i64)))),
        21 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 8) & 0x3) as i64) != (0x3 as i64))),
        22 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 8) & 0x3) as i64) != (0x3 as i64))) && (((((w >> 3) & 0xf) as i64) != (0xd as i64))),
        23 => (false),
        24 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 6) & 0x3) as i64) != (0x2 as i64))),
        25 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (((((w >> 0) & 0xf) as i64) != (0x0 as i64))) && (((((w >> 0) & 0xf) as i64) != (0x0 as i64))),
        26 => (!((((((w >> 10) & 0x3f) & 0x38) == 0x38)))) && (!((((((w >> 8) & 0xf) & 0xe) == 0xe)))) && (!((((((w >> 8) & 0xf) & 0xe) == 0xe)))),
        _ => true,
    }
}

